   scm.triggerWorkflow(
       aiTarget.owner,
       aiTarget.repo,
       ctx.workflowFile,
       JSON.stringify({
           concurrency_key: ctx.ticketKey,
           display_key: ctx.ticketKey,
           config_file: ctx.configFile,
           encoded_config: encodedCfg,
           project_key: projectKey || ''
       }),
       resolveDispatchRef(options.ref, ctx.customParams.aiRepository, ctx.config)
   );

   console.log('✅ Auto-started ' + ctx.label + ' for ' + ctx.ticketKey +
       ' [config=' + ctx.configFile + (projectKey ? ', project=' + projectKey : '') + ']');
   return true;
}
