echo "=== 3. canonical runner (last run):"
grep -E "passed|exit" /tmp/dmtools_final2.log | tail -2
echo "=== 4. named-function CRAP (final crap4js report):"
grep -E "^(triggerConfiguredWorkflowForTicket|triggerSmIfIdle|hasActiveTargetRun) js/common" /tmp/cov4/crap_final.txt
grep -E "^stampRequiredChecks js/common" /tmp/cov4/crap_final.txt
