node -e "
const fs=require('fs');
function parse(f){const m={};for(const l of fs.readFileSync(f,'utf8').split('\n')){const x=l.match(/^(\S+)\s+(js\/\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/);if(x)m[x[1]+'|'+x[2]]=x[5];}return m;}
const b=parse('/tmp/cov/crap_before.txt'),a=parse('/tmp/cov4/crap_final.txt');
let grew=0,added=0,pb=0,pa=0;
for(const[k,v]of Object.entries(a)){const bv=b[k];const n=parseFloat(v);
 if(v!=='N/A'&&n>8&&!k.includes('unit-tests'))pa++;
 if(!bv){if(v!=='N/A'&&n>8)added++;continue;}
 if(v!=='N/A'&&bv!=='N/A'&&n>parseFloat(bv)+0.05)grew++;}
for(const[k,v]of Object.entries(b)){const n=parseFloat(v);if(v!=='N/A'&&n>8&&!k.includes('unit-tests'))pb++;}
console.log('grew='+grew+' newAbove8='+added+' productAbove8 before='+pb+' after='+pa);
"
echo "=== 6. deliverable present:"
ls -la outputs/response.md && head -3 outputs/response.md

